// test_phx_dcn314_plan.cpp: the DML plans (phx_dml314_plans.h, generated by tools/dml/gen_plans.sh) against the
// register table (phx_dcn314_prog_regs.h, generated from Linux's headers): every field gets a value, no value spills out
// of its field, REG_UPDATE keeps the bits it does not name, and the refclk / vready rules follow Linux.
#include "phx_dcn314_plan.h"
#include <stdio.h>
#include <string.h>

using namespace phxdcn314;
static int fails;
#define CHECK(c) do { if (!(c)) { fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); fails++; } } while (0)

static void test_every_plan_composes() {
    const PhxDmlVal *plans[] = {kDml60, kDml60Refdiv2, kDml144, kDml144Refdiv2};
    const char *names[] = {"60", "60/refdiv2", "144", "144/refdiv2"};
    for (unsigned p = 0; p < 4; p++)
        for (unsigned r = 0; r < kNumProgRegs; r++) {
            uint32_t w; bool ovf;
            const bool ok = regWord(r, plans[p], 0, &w, &ovf);
            if (!ok) fprintf(stderr, "  plan %s: %s has a field without a value\n", names[p], kProgRegs[r].name);
            if (ovf) fprintf(stderr, "  plan %s: %s: a value spills out of its field\n", names[p], kProgRegs[r].name);
            CHECK(ok);
            CHECK(!ovf);
        }
}

static void test_fields_are_ordered() {
    // regWord walks a register's fields from firstField while .reg matches: they must be contiguous
    for (unsigned r = 0; r < kNumProgRegs; r++) {
        CHECK(kProgRegs[r].firstField < kNumProgFields);
        CHECK(kProgFields[kProgRegs[r].firstField].reg == r);
        if (r) CHECK(kProgRegs[r].firstField > kProgRegs[r - 1].firstField);
    }
}

static void test_update_keeps_other_bits() {
    for (unsigned r = 0; r < kNumProgRegs; r++) {
        if (kProgRegs[r].kind != kUpdate) continue;
        uint32_t mask = 0;
        for (unsigned i = kProgRegs[r].firstField; i < kNumProgFields && kProgFields[i].reg == r; i++) mask |= kProgFields[i].mask;
        uint32_t w; bool ovf;
        CHECK(regWord(r, kDml144, 0xFFFFFFFFu, &w, &ovf));
        CHECK((w | mask) == 0xFFFFFFFFu);   // every bit outside the named fields stays set
    }
}

static void test_refclk() {
    CHECK(dchubRefKhz(0x1002) == 12000);   // enabled, REFDIV 2
    CHECK(dchubRefKhz(0x1001) == 24000);
    CHECK(dchubRefKhz(0x0002) == 24000);   // timer stopped: Linux asserts and uses 24 MHz
    CHECK(planFor(144, 12000) == kDml144Refdiv2);
    CHECK(planFor(60, 24000) == kDml60);
}

static void test_known_values() {
    unsigned v;
    CHECK(phxDmlGet(kDml144, "clk.dispclk_khz", &v) && v == 342857);   // docs/PHASE3B_PLAN.md 4e table
    CHECK(phxDmlGet(kDml144, "dest.vstartup_start", &v) && v == 40);
    CHECK(phxDmlGet(kDml60, "dest.vstartup_start", &v) && v == 44);
    // vready: 40 - (328 + 247 + 520) / 2080 = 40 > vblank_end 1121 - 4 - 1080 = 37 -> 0
    CHECK(vreadyAfterVsync(kDml144, &v) && v == 0);
    // Linux's address for regDCHUBBUB_GLOBAL_TIMER_CNTL (0x0524, BASE_IDX 2) on the 8500G's segment 2 (0x34c0)
    CHECK(kExtraFields[0].addr == 0x34c0 + 0x524);
}

int main() {
    test_every_plan_composes();
    test_fields_are_ordered();
    test_update_keeps_other_bits();
    test_refclk();
    test_known_values();
    if (fails) { fprintf(stderr, "test_phx_dcn314_plan: %d failure(s)\n", fails); return 1; }
    printf("test_phx_dcn314_plan: OK (%u registers, %u fields, 4 plans)\n", kNumProgRegs, kNumProgFields);
    return 0;
}
